INSERT INTO books VALUES ('fundamental_biblical_truths', 'Fundamental Biblical Truths', 'Zac Poonen', 'Foundational Truths', '["Foundational Truth","Seeker"]', 'When God puts His Holy Spirit within man, that innermost part of us gets revived and it becomes alive. It&#039;s like a resurrection and that&#039;s why Christians are commanded to be baptized because in baptism we&#039;re testifying that a resurrection has taken place within our spirit.', 'fundamental_biblical_truths.jpg', 455, 553, '2026-09-01T11:52:44.272Z');
