INSERT INTO books VALUES ('all_that_jesus_taught', 'All That Jesus Taught', 'Zac Poonen', 'The Church & Leadership', '["The Church","Knowing God","Disciples"]', 'The Great Commission that Jesus gave His apostles consisted of TWO parts:
 (1) To preach the gospel to everyone (Mark 16:15, 16).
 (2) To make disciples, baptize them, and then teach them all that Jesus taught (Matt. 28:29, 20).', NULL, 1449, 2866, '2026-09-01T11:52:44.497Z');
