INSERT INTO books VALUES ('the_day_of_small_beginnings', 'The Day Of Small Beginnings', 'Zac Poonen', 'Foundational Truths', '["Foundational Truth","Disciples","Seeker"]', 'This book , a much needed spiritual challenge for any man or woman who longs to be used by God. Read some of the important lessons that Zac Poonen and his co workers learned as they sought to serve the Lord, building His church. Just as large doors swing on small hinges they learned that small decisions determined the quality of their work for the Lord.', 'the_day_of_small_beginnings.jpg', 228, 668, '2026-09-01T11:52:45.492Z');
